        customer_ids = [i for i in range(len(matrix)) if i != depot]

    # fallback coordinates if missing and matrix present
    if not coords and matrix is not None:
        n = len(matrix)
        coords = {i: (float(i), 0.0) for i in range(n)}

    # default demands
    for c in customer_ids:
        if c not in demand:
            if isinstance(instance, dict) and "demands" in instance and isinstance(instance["demands"], list) and isinstance(c, int) and c < len(instance["demands"]):
                demand[c] = int(instance["demands"][c])
            else:
                demand[c] = 1

    if capacity is None:
        total = 0
        for c in customer_ids:
            total += demand.get(c, 1)
        capacity = total

    customer_ids = [c for c in customer_ids if c != depot]
    if not customer_ids:
        return []

    # ensure deterministic order by angle / distance
    dx0, dy0 = coords[depot]
    def key_fn(c):
        x, y = coords[c]
        ang = 0.0
        if x != dx0 or y != dy0:
            ang = (y - dy0) / ((abs(x - dx0) + abs(y - dy0)) + 1e-9)
        return (ang, dist(depot, c), c)

    ordered = sorted(customer_ids, key=key_fn)

    # constructive: capacity-aware greedy chaining
    unserved = ordered[:]
    routes = []
    while unserved:
        route = []
        load = 0
        current = depot
        while True:
            best = None
            best_score = None
            for c in unserved:
                d = demand.get(c, 1)
                if load + d > capacity:
                    continue
                score = (dist(current, c), dist(depot, c), c)
                if best_score is None or score < best_score:
                    best_score = score
                    best = c
            if best is None:
                break
            route.append(best)
            load += demand.get(best, 1)
            current = best
            unserved.remove(best)
        if not route:
            c = unserved.pop(0)
            routes.append([c])
        else:
            routes.append(route)

    # local improvements
    routes = [two_opt(r) for r in routes]
    routes = relocate_between(routes)
    routes = [two_opt(r) for r in routes]
    routes = merge_empty(routes)

    # final repair: ensure all customers appear exactly once
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    missing = [c for c in customer_ids if seen.get(c, 0) == 0]
    dupes = [c for c, cnt in seen.items() if cnt > 1]

    if missing or dupes:
        flat = []
        seen2 = set()
        for r in routes:
            nr = []
            load = 0
            for c in r:
                if c in seen2:
                    continue
                if load + demand.get(c, 1) <= capacity:
                    nr.append(c)
                    load += demand.get(c, 1)
                    seen2.add(c)
            if nr:
                flat.append(nr)
        for c in missing:
            placed = False
            for r in flat:
                if route_load(r) + demand.get(c, 1) <= capacity:
                    best_j = 0
                    best_delta = None
                    for j in range(len(r) + 1):
                        prev = depot if j == 0 else r[j - 1]
                        nxt = depot if j == len(r) else r[j]
                        delta = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                        if best_delta is None or delta < best_delta:
                            best_delta = delta
                            best_j = j
                    r.insert(best_j, c)
                    placed = True
                    break
            if not placed:
                flat.append([c])
        routes = flat

    routes = [r for r in routes if r]
    return routes
